// For each i where sp2v_sig_err is valid, sp2v_sig_chk must hold its previous safe value
assert property (@(posedge clk_i) disable iff (!rst_ni)
  (sp2v_sig_err[i] |-> $stable(sp2v_sig_chk[i])));

// Assumption: legal states are enumerated in VALID_STATES (dependent on actual encoding)
assert property (@(posedge clk_i) disable iff (!rst_ni)
  (!(u_aes_ctr_fsm.u_state_regs inside {VALID_STATES})) |-> ##[0:5] alert_tx_o[1]);
